import hicstraw, numpy as np, pickle, os
urls={'H1':'https://4dn-open-data-public.s3.amazonaws.com/fourfront-webprod/wfoutput/0abd0cb2-6e62-492f-97a8-6cd19f814e99/4DNFI2TK7L2F.hic','HFF':'https://4dn-open-data-public.s3.amazonaws.com/fourfront-webprod/wfoutput/464f672a-ff4b-41ba-818c-535fd1e725ac/4DNFIPC7P27B.hic'}
for res in [5000,10000]:
 start=7000000; end=8500000
 n=(end-start)//res+1
 mats={}
