    mat[i,j]=r.counts; mat[j,i]=r.counts
  mats[name]=mat
  print(res,name,'nonnan',np.isfinite(mat).sum(),'max',np.nanmax(mat))
 np.savez(f'mat_{res}_7000_8500.npz', start=start, res=res, H1=mats['H1'], HFF=mats['HFF'])
