TARGET=(7629950,7809597)
def read(fn):
 with gzip.open(fn,'rt') as f:
  h=f.readline()
  out={}
  for line in f:
   c=line.rstrip('\\n').split('\\t')
   if c[0]=='chr12' and c[3]=='chr12':
    s1,e1,s2,e2=map(int,[c[1],c[2],c[4],c[5]])
    if s1<e1 and s2<e2:
     key=(min(s1,s2),max(s1,s2),min(e1,e2) if s1<s2 else max(e1,e2))
    # store normalized left/right coordinates
    if s1<=s2: key=(s1,e1,s2,e2)
    else: key=(s2,e2,s1,e1)
    out[key]=(int(c[10]),float(c[11]),float(c[15]))
 return out
